/**
 * The renormalisation conditions as a linear system A * delta = -Delta,
 * with delta = (dm11, dm22, dm12, dl1, dl2, dl3, dl5). Conditions are the
 * two tadpoles plus the CP-even (1,1), (2,2), (1,2), one CP-odd and one
 * charged Hessian entry, following Eqs. (3.59)-(3.63) of arXiv:1803.02846.
 */
inline void fill_ct_matrix(double v1, double v2, CTMatrix &A) {
  A[0][0] = v1;
  A[0][1] = 0;
  A[0][2] = -v2;
  A[0][3] = (1.0/2.0)*pow(v1, 3);
  A[0][4] = 0;
  A[0][5] = (1.0/2.0)*v1*pow(v2, 2);
  A[0][6] = (1.0/2.0)*v1*pow(v2, 2);
  A[1][0] = 0;
  A[1][1] = v2;
  A[1][2] = -v1;
  A[1][3] = 0;
  A[1][4] = (1.0/2.0)*pow(v2, 3);
  A[1][5] = (1.0/2.0)*pow(v1, 2)*v2;
  A[1][6] = (1.0/2.0)*pow(v1, 2)*v2;
  A[2][0] = 1;
  A[2][1] = 0;
  A[2][2] = 0;
  A[2][3] = (3.0/2.0)*pow(v1, 2);
  A[2][4] = 0;
  A[2][5] = (1.0/2.0)*pow(v2, 2);
  A[2][6] = (1.0/2.0)*pow(v2, 2);
  A[3][0] = 0;
  A[3][1] = 1;
  A[3][2] = 0;
  A[3][3] = 0;
  A[3][4] = (3.0/2.0)*pow(v2, 2);
  A[3][5] = (1.0/2.0)*pow(v1, 2);
  A[3][6] = (1.0/2.0)*pow(v1, 2);
  A[4][0] = 0;
  A[4][1] = 0;
  A[4][2] = -1;
  A[4][3] = 0;
  A[4][4] = 0;
  A[4][5] = v1*v2;
  A[4][6] = v1*v2;
  A[5][0] = 1;
  A[5][1] = 0;
  A[5][2] = 0;
  A[5][3] = (1.0/2.0)*pow(v1, 2);
  A[5][4] = 0;
  A[5][5] = (1.0/2.0)*pow(v2, 2);
  A[5][6] = -1.0/2.0*pow(v2, 2);
  A[6][0] = 1;
  A[6][1] = 0;
  A[6][2] = 0;
  A[6][3] = (1.0/2.0)*pow(v1, 2);
  A[6][4] = 0;
  A[6][5] = (1.0/2.0)*pow(v2, 2);
  A[6][6] = 0;
}

